insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('4830d69f-8d8c-4322-b5f1-d8b8d94e757c', 'eb6df17f-05d4-49df-b626-ba5d585672a9', 'kolay'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde bir anlatım bozukluğu vardır?', 'Gereksiz sözcük kullanımından kaynaklanan anlatım bozukluğunu fark eder.', '''Sevindirmek'' ve ''mutlu etmek'' aynı anlama geldiği için bu iki ifadenin bir arada kullanılması gereksiz tekrara, dolayısıyla anlatım bozukluğuna yol açmıştır. Diğer cümlelerde böyle bir tekrar yoktur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4830d69f-8d8c-4322-b5f1-d8b8d94e757c', 'Bu haber beni hem çok sevindirdi hem de mutlu etti.', true, 0);
